def is_palindrome(x: int) -> bool:
    # Returns True if x is a palindrome
    s = str(x)
    return s == s[::-1]

def minimumCost(nums):
    nums = sorted(nums)
    median = nums[len(nums) // 2]

    def cost(target):
        return sum(abs(x - target) for x in nums)

    # Nearest palindrome <= median (1 is a palindrome, so this stops)
    lo = median
    while not is_palindrome(lo):
        lo -= 1
    # Nearest palindrome >= median
    hi = median
    while not is_palindrome(hi):
        hi += 1

    return min(cost(lo), cost(hi))
